export function Epic({
  title = "{{title}}",
  doneStories = {{doneStories}},
  totalStories = {{totalStories}},
  percent = {{percent}},
  status = "{{status}}",
  accent = "{{accent}}",
}) {
  const badge = {
    "on-track": { text: "On track", bg: "#cdeedb", color: "#1a7a4c" },
    "at-risk": { text: "At risk", bg: "#fbe6bd", color: "#8a5d00" },
    done: { text: "Done", bg: accent, color: "#241430" },
  }[status] ?? { text: "On track", bg: "#cdeedb", color: "#1a7a4c" };
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", background: "#FAF7F2",
      padding: "16px 18px", borderRadius: 12, maxWidth: 380, boxSizing: "border-box", border: "1.5px solid #24143014" }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8, flexWrap: "wrap" }}>
        <h3 style={{ margin: 0, fontSize: 16 }}>{title}</h3>
        <span style={{ fontSize: 11, fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.03em",
          padding: "3px 9px", borderRadius: 999, background: badge.bg, color: badge.color }}>{badge.text}</span>
      </div>
      <p style={{ margin: "10px 0 6px", fontSize: 13, color: "#241430cc" }}>{doneStories} of {totalStories} stories done</p>
      <div style={{ height: 8, borderRadius: 999, background: "#24143014", overflow: "hidden" }}>
        <div style={{ height: "100%", borderRadius: 999, background: accent, width: `${percent}%` }} />
      </div>
      <p style={{ margin: "6px 0 0", fontSize: 12, fontWeight: 600, color: "#241430b3" }}>{percent}% complete</p>
    </div>
  );
}
